/** com.khnp.pels.api.TstEventStrokeByPageList */
SELECT T2.POINT_PATH
  FROM GE_MP_CHECK_EVENT_M T1
  JOIN GE_MP_CHECK_EVENT_STRK_S T2
    ON T1.EVENT_SEQ = T2.EVENT_SEQ
 WHERE T1.TST_UNQ_KY_VAL = #{TST_UNQ_KY_VAL, jdbcType=BIGINT}
       T1.PAGE_NO = #{PAGE_NO, jdbcType=INTEGER}
       T1.EVENT_TYP = #{EVENT_TYP, jdbcType=INTEGER}
 ORDER
    BY T1.STROKE_SEQ

SELECT GE_PL_CHECK_EVENT_SEQ.NEXTVAL
  FROM DUAL
CONNECT BY LEVEL <= #{value, jdbcType=INTEGER}

mapper.insert:
/** com.khnp.pels.api.TstEventBatchInsert */
INSERT
  INTO GE_MP_CHECK_EVENT_M
     ( EVENT_SEQ
     , EVENT_TYP
     , TST_UNQ_KY_VAL
     , PAGE_NO
     , PDF_PAGE_NO
     , STROKE_SEQ
     , USER_ID
     , EVENT_DT
     )
VALUES
     ( #{EVENT_SEQ, jdbcType=BIGINT}
     , #{EVENT_TYP, jdbcType=INTEGER}
     , #{TST_UNQ_KY_VAL, jdbcType=BIGINT}
     , #{PAGE_NO, jdbcType=INTEGER}
     , #{PDF_PAGE_NO, jdbcType=INTEGER}
     , #{STROKE_SEQ, jdbcType=INTEGER}
     , #{USER_ID, jdbcType=VARCHAR}
     , TO_TIMESTAMP(#{EVENT_DT, jdbcType=VARCHAR},'YYYY-MM-DD"T"HH24:MI:SS.FF3')
     )

/** com.khnp.pels.api.TstEventInsert */

    SELECT GE_PL_CHECK_EVENT_SEQ.NEXTVAL FROM DUAL

INSERT
  INTO GE_MP_CHECK_EVENT_M
     ( EVENT_SEQ
     , EVENT_TYP
     , TST_UNQ_KY_VAL
     , PAGE_NO
     , PDF_PAGE_NO
     , STROKE_SEQ
     , USER_ID
     , EVENT_DT
     )
VALUES
     ( #{EVENT_SEQ, jdbcType=BIGINT}
     , #{EVENT_TYP, jdbcType=INTEGER}
     , #{TST_UNQ_KY_VAL, jdbcType=BIGINT}
     , #{PAGE_NO, jdbcType=INTEGER}
     , #{PDF_PAGE_NO, jdbcType=INTEGER}
     , #{STROKE_SEQ, jdbcType=INTEGER}
     , #{USER_ID, jdbcType=VARCHAR}
     , TO_TIMESTAMP(#{EVENT_DT, jdbcType=VARCHAR},'YYYY-MM-DD"T"HH24:MI:SS.FF3')
     )

/** com.khnp.pels.api.TstEventStrokeInsert */
INSERT
  INTO GE_MP_CHECK_EVENT_STRK_S
     ( EVENT_SEQ
     , POINT_PATH
     , STROKE_COLOR
     , STROKE_WIDTH
     )
VALUES
     ( #{EVENT_SEQ, jdbcType=BIGINT}
     , #{POINT_PATH, jdbcType=BLOB}
     , #{STROKE_COLOR, jdbcType=BIGINT}
     , #{STROKE_WIDTH, jdbcType=NUMERIC}
     )
